import { Show, splitProps, type JSX } from 'solid-js';
import { getButtonStyleKeys, isButtonDisabled } from '../lib/core';
import type { ButtonBaseProps } from '../lib/core';
import styles from './button.module.scss';

export interface ButtonProps extends JSX.ButtonHTMLAttributes<HTMLButtonElement>, Omit<ButtonBaseProps, 'asChild'> {}

/**
 * SolidJS Button：复用 core 的样式 key 与禁用判定，样式来自共享 SCSS。
 */
export function Button(props: ButtonProps) {
	const [local, rest] = splitProps(props, ['variant', 'size', 'loading', 'children', 'disabled', 'class', 'type']);
	const styleKeys = () => getButtonStyleKeys(local.variant, local.size);
	const isDisabled = () => isButtonDisabled(local.disabled, local.loading);

	return (
		<button
			{...rest}
			class={`${styles[styleKeys().base]} ${styles[styleKeys().variant]} ${styles[styleKeys().size]} ${local.class ?? ''}`}
			disabled={isDisabled()}
			type={local.type ?? 'button'}>
			<Show when={local.loading}>
				<svg
					class={styles.spinner}
					xmlns="http://www.w3.org/2000/svg"
					width="16"
					height="16"
					viewBox="0 0 24 24"
					fill="none"
					stroke="currentColor"
					stroke-width="2"
					stroke-linecap="round"
					stroke-linejoin="round"
					aria-hidden="true">
					<circle cx="12" cy="12" r="10" />
				</svg>
			</Show>
			{local.children}
		</button>
	);
}

export default Button;

@use '../../../styles/variables/colors' as *;

.button {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	gap: $spacing-2;
	white-space: nowrap;
	border-radius: $radius;
	font-size: $text-sm;
	font-weight: $font-medium;
	transition: all $transition-fast;
	cursor: pointer;
	outline: none;

	&:focus-visible {
		outline: none;
		box-shadow:
			0 0 0 2px $background,
			0 0 0 4px $ring;
	}

	&:disabled,
	&.disabled {
		pointer-events: none;
		opacity: 0.5;
		cursor: not-allowed;
	}

	svg {
		pointer-events: none;
		width: 1em;
		height: 1em;
	}

	// 尺寸变体
	&.sizeDefault {
		height: 2.25rem;
		padding: 0 $spacing-4;

		&.hasIcon {
			padding-inline: $spacing-3;
		}
	}

	&.sizeXs {
		height: 1.5rem;
		gap: $spacing-1;
		border-radius: $radius;
		padding: 0 $spacing-2;
		font-size: $text-xs;

		svg {
			width: 0.75rem;
			height: 0.75rem;
		}

		&.hasIcon {
			padding-inline: $spacing-1_5;
		}
	}

	&.sizeSm {
		height: 2rem;
		border-radius: $radius-sm;
		padding: 0 $spacing-3;
		font-size: $text-xs;

		&.hasIcon {
			padding-inline: $spacing-2;
			gap: $spacing-1;
		}
	}

	&.sizeLg {
		height: 2.5rem;
		border-radius: $radius-md;
		padding: 0 $spacing-6;
		font-size: $text-base;

		&.hasIcon {
			padding-inline: $spacing-4;
		}
	}

	&.sizeIcon {
		height: 2.25rem;
		width: 2.25rem;
		padding: 0;
	}

	&.sizeIconXs {
		height: 1.5rem;
		width: 1.5rem;
		border-radius: $radius;
		padding: 0;

		svg {
			width: 0.75rem;
			height: 0.75rem;
		}
	}

	&.sizeIconSm {
		height: 2rem;
		width: 2rem;
		padding: 0;
	}

	&.sizeIconLg {
		height: 2.5rem;
		width: 2.5rem;
		padding: 0;
	}

	// 样式变体
	&.variantDefault {
		background-color: $primary;
		color: $primary-foreground;
		border: none;
		box-shadow: $shadow-sm;

		&:hover:not(:disabled) {
			background-color: $primary-hover;
		}

		&:active:not(:disabled) {
			background-color: $primary-active;
		}
	}

	&.variantDestructive {
		background-color: $destructive;
		color: $destructive-foreground;
		border: none;
		box-shadow: $shadow-sm;

		&:hover:not(:disabled) {
			background-color: $destructive-hover;
		}
	}

	&.variantOutline {
		background-color: transparent;
		color: $foreground;
		border: 1px solid $border;
		box-shadow: $shadow-sm;

		&:hover:not(:disabled) {
			background-color: $accent;
			color: $accent-foreground;
		}
	}

	&.variantSecondary {
		background-color: $secondary;
		color: $secondary-foreground;
		border: none;
		box-shadow: $shadow-sm;

		&:hover:not(:disabled) {
			background-color: $secondary-hover;
		}
	}

	&.variantGhost {
		background-color: transparent;
		color: $foreground;

		&:hover:not(:disabled) {
			background-color: $accent;
			color: $accent-foreground;
		}
	}

	&.variantLink {
		background-color: transparent;
		color: $primary;
		text-decoration: underline;
		text-underline-offset: 4px;

		&:hover:not(:disabled) {
			text-decoration: none;
		}
	}
}
